import pandas as pd
df = env['raw_df']
issues = {'schema_drift': False, 'type_errors': [], 'missing_values': {}, 'duplicates': 0, 'outlier_count': 0}
expected_cols = ['date', 'product', 'quantity', 'revenue']
actual_cols = list(df.columns)
if set(expected_cols).symmetric_difference(set(actual_cols)):
    issues['schema_drift'] = True
    issues['unexpected_columns'] = [c for c in actual_cols if c not in expected_cols]
    issues['missing_columns'] = [c for c in expected_cols if c not in actual_cols]
for col in ['quantity', 'revenue']:
    if col in df.columns:
        converted = pd.to_numeric(df[col], errors='coerce')
        if converted.isnull().sum() > df[col].isnull().sum():
            issues['type_errors'].append(col)
missing = df.isnull().sum()
issues['missing_values'] = {k: int(v) for k, v in missing.items() if v > 0}
issues['duplicates'] = int(df.duplicated().sum())
if 'revenue' in df.columns:
    revenue_numeric = pd.to_numeric(df['revenue'], errors='coerce').dropna()
    if len(revenue_numeric) > 0:
        Q1 = revenue_numeric.quantile(0.25)
        Q3 = revenue_numeric.quantile(0.75)
        IQR = Q3 - Q1
        issues['outlier_count'] = int(((revenue_numeric < Q1 - 1.5*IQR) | (revenue_numeric > Q3 + 1.5*IQR)).sum())
env['detected_issues'] = issues

import pandas as pd
df = env['raw_df'].copy()
issues = env['detected_issues']
repairs_log = []
expected_cols = ['date', 'product', 'quantity', 'revenue']
if issues.get('schema_drift'):
    available = [c for c in expected_cols if c in df.columns]
    df = df[available]
    repairs_log.append('Removed unexpected columns; kept only expected schema')
for col in issues.get('type_errors', []):
    if col in df.columns:
        df[col] = pd.to_numeric(df[col], errors='coerce')
        repairs_log.append('Coerced ' + col + ' to numeric')
for col, count in issues.get('missing_values', {}).items():
    if col in df.columns and count > 0:
        if df[col].dtype in ['float64', 'int64']:
            df[col].fillna(df[col].median(), inplace=True)
        else:
            mode_val = df[col].mode()
            df[col].fillna(mode_val.iloc[0] if len(mode_val) > 0 else 'Unknown', inplace=True)
        repairs_log.append('Imputed ' + str(count) + ' missing values in ' + col)
if issues.get('duplicates', 0) > 0:
    df = df.drop_duplicates()
    repairs_log.append('Removed ' + str(issues['duplicates']) + ' duplicate rows')
env['repaired_df'] = df
env['repairs_log'] = repairs_log

import pandas as pd
df = env['repaired_df']
revalidation = {
    'remaining_missing': int(df.isnull().sum().sum()),
    'remaining_duplicates': int(df.duplicated().sum()),
    'row_count': int(len(df)),
    'columns': list(df.columns),
    'column_types': {col: str(dtype) for col, dtype in df.dtypes.items()}
}
env['revalidation'] = revalidation

